(() => {
  const id=x=>document.getElementById(x),safe=v=>typeof esc==='function'?esc(v):String(v??'');
  let proofShot=null,proofMode='cinematic';
  const checks={
    living_scene:['internal_motion_visible','material_motion_independent','identity_stable','camera_restrained','loop_or_join_clean'],
    cinematic:['story_action_readable','coverage_sufficient','continuity_controlled','shot_progression_present','pacing_music_directed']
  };

  function ensureDialogs(){
    if(!id('proofDialog'))document.body.insertAdjacentHTML('beforeend',`<dialog id="proofDialog"><form method="dialog"><h3>Review shot proof</h3><p id="proofIntro" class="muted"></p><label>Proof video<select id="proofAsset"></select></label><label>Production mode<select id="proofMode"><option value="cinematic">Cinematic</option><option value="living_scene">Living scene</option></select></label><div id="proofChecks" class="review-checks"></div><label>Notes<textarea id="proofNotes" rows="2"></textarea></label><div class="dialog-actions"><button value="cancel" class="soft">Cancel</button><button id="recordProof" type="button">Record proof</button></div></form></dialog>`);
    if(!id('fxDialog'))document.body.insertAdjacentHTML('beforeend',`<dialog id="fxDialog"><form method="dialog"><h3>Effects for this film</h3><p class="muted">Only production-approved canonical effects can be locked. Proof-required and unavailable effects remain visible but disabled.</p><div id="fxChoices" class="fx-choices"></div><div class="dialog-actions"><button value="cancel" class="soft">Cancel</button><button id="saveFx" type="button" class="soft">Save selection</button><button id="lockFx" type="button">Save & lock</button></div></form></dialog>`);
    if(!id('finalAcceptDialog'))document.body.insertAdjacentHTML('beforeend',`<dialog id="finalAcceptDialog"><form method="dialog"><h3>Creative final review</h3><p class="muted">Technical QC cannot accept the film. Confirm the full export was actually reviewed.</p><div id="finalChecks" class="review-checks"></div><label>Acceptance instruction<textarea id="finalInstruction" rows="3" placeholder="I reviewed the full export and accept this version."></textarea></label><div class="dialog-actions"><button value="cancel" class="soft">Cancel</button><button id="acceptFinal" type="button">Accept final film</button></div></form></dialog>`);
  }

  function nice(x){return String(x||'').replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());}
  async function openProof(shot){
    ensureDialogs();proofShot=shot;
    try{
      const [template,operating]=await Promise.all([toolCall('shots.template',{project_id:projectId()}),toolCall('operating.status',{project_id:projectId()}).catch(()=>({}))]);
      const videos=(template.assets||[]).filter(a=>String(a.content_type||'').startsWith('video/'));
      if(!videos.length){document.getElementById('productionStatus').textContent='A shot proof must be a ready, hashed video asset. Add or render the proof video first.';return;}
      id('proofAsset').innerHTML=videos.map(a=>`<option value="${safe(a.id)}">${safe(a.filename)}</option>`).join('');
      const overall=operating.production_mode||'cinematic';proofMode=overall==='living_scene'?'living_scene':'cinematic';id('proofMode').value=proofMode;id('proofMode').disabled=overall!=='hybrid';id('proofIntro').textContent=`${shot} · select the actual temporal proof video and verify the creative behavior.`;renderProofChecks();id('proofDialog').showModal();
    }catch(e){id('productionStatus').textContent=e.message;}
  }
  function renderProofChecks(){proofMode=id('proofMode').value;id('proofChecks').innerHTML=checks[proofMode].map(k=>`<label class="review-check"><input type="checkbox" data-proof-check="${k}"><span><strong>${nice(k)}</strong><small>Confirmed in the exported proof at normal playback.</small></span></label>`).join('');}
  async function recordProof(){const selected={};document.querySelectorAll('[data-proof-check]').forEach(x=>selected[x.dataset.proofCheck]=x.checked);if(Object.values(selected).some(v=>!v)){id('productionStatus').textContent='All required mode-aware proof checks must be confirmed.';return;}try{await toolCall('proofs.record',{project_id:projectId(),shot_id:proofShot,proof_asset_id:id('proofAsset').value,production_mode:id('proofMode').value,checks:selected,notes:id('proofNotes').value.trim()});id('proofDialog').close();const instruction=prompt(`Proof recorded for ${proofShot}. Enter the explicit acceptance instruction, or Cancel to leave it Needs review.`);if(instruction?.trim())await toolCall('proofs.accept',{project_id:projectId(),shot_id:proofShot,instruction:instruction.trim()});await refreshAll();}catch(e){id('productionStatus').textContent=e.message;}}

  function enhanceShotCards(){document.querySelectorAll('[data-shot-card]').forEach(card=>{if(card.querySelector('[data-review-proof]'))return;const b=document.createElement('button');b.type='button';b.className='soft proof-button';b.dataset.reviewProof='1';b.textContent='Review proof';b.onclick=()=>openProof(card.dataset.shotCard);card.appendChild(b);});}

  async function openFx(){ensureDialogs();try{const [reg,status]=await Promise.all([toolCall('fx.registry',{project_id:projectId()}),toolCall('fx.status',{project_id:projectId()})]);const selected=new Set([...(status.requested_effects||[]),...(status.requested_transitions||[])].map(x=>typeof x==='string'?x:x.id));id('fxChoices').innerHTML=(reg.effects||[]).map(f=>{const transition=(f.implementation||{}).kind==='runtime_transition';const allowed=['approved','conditional'].includes(f.gate_status);return `<label class="fx-choice ${allowed?'':'disabled'}"><input type="checkbox" data-fx-id="${safe(f.id)}" data-fx-kind="${transition?'transition':'effect'}" ${selected.has(f.id)?'checked':''} ${allowed?'':'disabled'}><span><strong>${safe(f.name||f.id)}</strong><small>${safe(f.family||'effect')} · ${safe(f.gate_status||'unknown')}${f.gate_status==='conditional'?' · requires preflight':''}</small></span></label>`}).join('');id('fxDialog').showModal();}catch(e){id('productionStatus').textContent=e.message;}}
  function chosenFx(){const effects=[],transitions=[];document.querySelectorAll('[data-fx-id]:checked').forEach(x=>(x.dataset.fxKind==='transition'?transitions:effects).push({id:x.dataset.fxId}));return{effects,transitions};}
  async function saveFx(lockAfter=false){const c=chosenFx();if(!c.effects.length&&!c.transitions.length){id('productionStatus').textContent='Choose at least one approved effect or transition.';return;}try{await toolCall('fx.set_requirements',{project_id:projectId(),...c,seed:302,allow_conditional:[],conditional_preflight:{}});if(lockAfter){id('productionStatus').textContent='Running canonical FX precompile gate and smoke tests…';await toolCall('fx.lock',{project_id:projectId()});}id('fxDialog').close();id('productionStatus').textContent=lockAfter?'Effects locked and live-verified.':'Effect requirements saved.';await refreshAll();}catch(e){id('productionStatus').textContent=e.message;}}

  async function finalizeProofSet(){try{const s=await toolCall('proofs.status',{project_id:projectId()});if(!s.proof_count||s.accepted_count!==s.proof_count){id('productionStatus').textContent=`Accept every shot proof first (${s.accepted_count||0}/${s.proof_count||0}).`;return;}const instruction=prompt('All shot proofs are accepted. Enter the instruction accepting the complete proof set.');if(!instruction?.trim())return;await toolCall('proofs.finalize',{project_id:projectId(),instruction:instruction.trim()});id('productionStatus').textContent='Complete shot proof set accepted. Continue production to verify the gate.';await refreshAll();}catch(e){id('productionStatus').textContent=e.message;}}

  async function openFinalAccept(){ensureDialogs();try{const [qc,t]=await Promise.all([toolCall('final_qc.status',{project_id:projectId()}),toolCall('shots.template',{project_id:projectId()})]);if(!qc.technical_pass){id('productionStatus').textContent='Run and pass technical QC before creative acceptance.';return;}const required=['scripted_visuals_present','production_mode_visible','no_placeholder_substitution','pacing_and_transitions_accepted','full_export_reviewed_normal_speed'];id('finalChecks').innerHTML=required.map(k=>`<label class="review-check"><input type="checkbox" data-final-check="${k}"><span><strong>${nice(k)}</strong><small>Confirmed across the full exported film.</small></span></label>`).join('');id('finalAcceptDialog').dataset.shots=JSON.stringify((t.shots||[]).map(s=>s.shot_id));id('finalAcceptDialog').showModal();}catch(e){id('productionStatus').textContent=e.message;}}
  async function acceptFinal(){const mode={};document.querySelectorAll('[data-final-check]').forEach(x=>mode[x.dataset.finalCheck]=x.checked);if(Object.values(mode).some(v=>!v)){id('productionStatus').textContent='Confirm every creative final-review check.';return;}const instruction=id('finalInstruction').value.trim();if(!instruction){id('productionStatus').textContent='An explicit final acceptance instruction is required.';return;}try{const shots=JSON.parse(id('finalAcceptDialog').dataset.shots||'[]');await toolCall('final_qc.accept_creative',{project_id:projectId(),verified_shot_ids:shots,mode_aware_checks:mode,instruction});id('finalAcceptDialog').close();id('productionStatus').textContent='Final film creatively accepted. Continue production to verify FINAL QC.';await refreshAll();}catch(e){id('productionStatus').textContent=e.message;}}

  function installButtons(){
    ensureDialogs();
    const assemble=document.querySelector('#surface-assemble .surface-actions');if(assemble&&!id('configureFx')){const b=document.createElement('button');b.id='configureFx';b.className='soft';b.textContent='Choose effects';b.onclick=openFx;assemble.insertBefore(b,id('verifyFx'));}
    const shots=document.querySelector('#surface-shots .surface-actions');if(shots&&!id('finalizeProofs')){const b=document.createElement('button');b.id='finalizeProofs';b.className='soft';b.textContent='Accept proof set';b.onclick=finalizeProofSet;shots.appendChild(b);}
    const finish=document.querySelector('#surface-finish .surface-actions');if(finish&&!id('acceptCreativeFinal')){const b=document.createElement('button');b.id='acceptCreativeFinal';b.className='soft';b.textContent='Creative review';b.onclick=openFinalAccept;finish.insertBefore(b,id('archiveProject'));}
    id('proofMode')?.addEventListener('change',renderProofChecks);id('recordProof')?.addEventListener('click',recordProof);id('saveFx')?.addEventListener('click',()=>saveFx(false));id('lockFx')?.addEventListener('click',()=>saveFx(true));id('acceptFinal')?.addEventListener('click',acceptFinal);
  }
  const observer=new MutationObserver(enhanceShotCards);const host=id('shotsGrid');if(host)observer.observe(host,{childList:true,subtree:true});installButtons();setInterval(enhanceShotCards,1500);
})();
